tool_input.content:
.poi-panel {
    position:  fixed;
    top:  80px;
    right:  16px;
    background-color:  rgba(255, 255, 255, 0.95);
    border:  1px solid #ddd;
    border-radius:  8px;
    padding:  16px;
    box-shadow:  0 2px 8px rgba(0, 0, 0, 0.15);
    z-index:  400;
    min-width:  180px;
    max-width:  220px;
}

.poi-section {
    margin-bottom:  16px;
    padding-bottom:  12px;
    border-bottom:  1px solid #eee;
}

.poi-section:last-child {
    margin-bottom:  0;
    padding-bottom:  0;
    border-bottom:  none;
}

.poi-section h4 {
    margin:  0 0 10px 0;
    font-size:  13px;
    font-weight:  600;
    color:  #333;
}

.poi-select {
    width:  100%;
    padding:  8px 10px;
    border:  1px solid #ddd;
    border-radius:  4px;
    font-size:  12px;
    background-color:  #fff;
    cursor:  pointer;
    transition:  border-color 0.2s;
}

.poi-select:focus {
    outline:  none;
    border-color:  #2196F3;
}

.poi-checkbox-group {
    display:  flex;
    flex-direction:  column;
    gap:  8px;
}

.poi-checkbox {
    display:  flex;
    align-items:  center;
    gap:  8px;
    font-size:  12px;
    color:  #555;
    cursor:  pointer;
    user-select:  none;
}

.poi-checkbox input[type="checkbox"] {
    width:  16px;
    height:  16px;
    cursor:  pointer;
    accent-color:  #2196F3;
}

.poi-checkbox span {
    flex:  1;
}

.poi-checkbox:hover {
    color:  #333;
}
